\version "2.27.2"
% automatically converted by musicxml2ly from 41f-StaffGroups-Overlapping.xml
\pointAndClickOff

\header {
  texidoc = "MusicXML allows for overlapping part groups, but many applications
    do not support that, requiring that they are properly nested instead. In
    this test, ‘Group 1’ (with a bracket) goes from staff 1 to 4, and ‘Group 2’
    (also with a bracket) goes from staff 3 to 5."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c' {
  \clef "treble" \time 4/4 \key c \major R1 \bar "|."
}

PartPTwoVoiceOne = \relative c' {
  \clef "treble" \time 4/4 \key c \major R1 \bar "|."
}

PartPThreeVoiceOne = \relative c' {
  \clef "treble" \time 4/4 \key c \major R1 \bar "|."
}

PartPFourVoiceOne = \relative c' {
  \clef "treble" \time 4/4 \key c \major R1 \bar "|."
}

PartPFiveVoiceOne = \relative c' {
  \clef "treble" \time 4/4 \key c \major R1 \bar "|."
}


% The score definition
\score {
  <<
    \new StaffGroup \with {
      \consists "Instrument_name_engraver"
    } <<
      \set StaffGroup.instrumentName = "Group 1"
      \set StaffGroup.shortInstrumentName = "Gr1"
      \new Staff = "P1" <<
        \override Staff.InstrumentName.self-alignment-X = #RIGHT
        \override Staff.InstrumentName.padding = #1
        \context Staff <<
          \mergeDifferentlyDottedOn
          \mergeDifferentlyHeadedOn
          \context Voice = "PartPOneVoiceOne" {
            \PartPOneVoiceOne
          }
        >>
      >>
      \new Staff = "P2" <<
        \override Staff.InstrumentName.self-alignment-X = #RIGHT
        \override Staff.InstrumentName.padding = #1
        \context Staff <<
          \mergeDifferentlyDottedOn
          \mergeDifferentlyHeadedOn
          \context Voice = "PartPTwoVoiceOne" {
            \PartPTwoVoiceOne
          }
        >>
      >>
      \new StaffGroup \with {
        \consists "Instrument_name_engraver"
      } <<
        \set StaffGroup.instrumentName = "Group 2"
        \set StaffGroup.shortInstrumentName = "Grp2"
        \new Staff = "P3" <<
          \override Staff.InstrumentName.self-alignment-X = #RIGHT
          \override Staff.InstrumentName.padding = #1
          \context Staff <<
            \mergeDifferentlyDottedOn
            \mergeDifferentlyHeadedOn
            \context Voice = "PartPThreeVoiceOne" {
              \PartPThreeVoiceOne
            }
          >>
        >>
        \new Staff = "P4" <<
          \override Staff.InstrumentName.self-alignment-X = #RIGHT
          \override Staff.InstrumentName.padding = #1
          \context Staff <<
            \mergeDifferentlyDottedOn
            \mergeDifferentlyHeadedOn
            \context Voice = "PartPFourVoiceOne" {
              \PartPFourVoiceOne
            }
          >>
        >>
      >>
    >>
    \new Staff = "P5" <<
      \context Staff <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPFiveVoiceOne" {
          \PartPFiveVoiceOne
        }
      >>
    >>
  >>
  \layout {}
  % To create MIDI output, uncomment the following line:
  % \midi { \tempo 4 = 100 }
}
